FROM cur c FULL OUTER JOIN prev p USING(asset_name) WHERE previous IS NOT NULL AND (c.asset_name IS NULL OR p.asset_name IS NULL OR c.metadata_json!=p.metadata_json);
UPDATE ${t('inventory_runs_v2')} SET status='COMPLETE',finished_at=CURRENT_TIMESTAMP(),asset_count=@expected,previous_run=previous,iam_status=@iam WHERE run_id=@run;
