  if (service === 'serviceusage.googleapis.com' && type === 'Service') return 'Enabled APIs';
  if (/^(Revision|Execution|Build|Backup|SecretVersion|DockerImage|ReportDetail)$/.test(type)) return 'History & versions';
  if (service === 'compute.googleapis.com' && /^(Network|Subnetwork|Route|Firewall|FirewallPolicy|Router|Address|ForwardingRule|VpnGateway|TargetVpnGateway|VpnTunnel|Interconnect|InterconnectAttachment|BackendService|UrlMap|Target.*Proxy|HealthCheck|NetworkEndpointGroup|ServiceAttachment|PacketMirroring)$/.test(type)
      || /^(vpcaccess|servicenetworking|networkconnectivity|networkservices|dns)\.googleapis\.com$/.test(service)) return 'Networking';
  if (service === 'firestore.googleapis.com' && /^(Index|Field|BackupSchedule)$/.test(type)) return 'Configuration & metadata';
  if (/^(iam|apikeys|identitytoolkit|secretmanager|recaptchaenterprise|firebaserules|cloudkms)\.googleapis\.com$/.test(service)) return 'Identity & security';
  if (service === 'run.googleapis.com' && /^(Service|Job|WorkerPool)$/.test(type)
      || service === 'cloudfunctions.googleapis.com' && type === 'Function'
      || service === 'compute.googleapis.com' && /^(Instance|Disk|Image|Snapshot|InstanceGroup|InstanceGroupManager)$/.test(type)
      || service === 'storage.googleapis.com' && type === 'Bucket'
      || service === 'artifactregistry.googleapis.com' && type === 'Repository'
      || service === 'eventarc.googleapis.com' && type === 'Trigger'
      || /^(bigquery|firestore|sqladmin|redis|memcache|file|alloydb|bigtableadmin|spanner|container|pubsub)\.googleapis\.com$/.test(service)
      || service === 'aiplatform.googleapis.com' && /^(Endpoint|Model|ReasoningEngine)$/.test(type)
      || service === 'cloudscheduler.googleapis.com' && type === 'Job') return 'Workloads & data';
  if (/^(cloudresourcemanager|cloudbilling|firebase|logging|monitoring|dataplex|cloudquotas|osconfig|discoveryengine|storageinsights)\.googleapis\.com$/.test(service)
      || service === 'compute.googleapis.com' && /^(Project|InstanceSettings|InstanceTemplate)$/.test(type)) return 'Configuration & metadata';
  return 'Other / review';
}
