for(const s of services){
 const project=projectIds.get(s.name.split('/').slice(0,2).join('/'));
 if(!project||!c.scopes.includes('projects/'+project))throw Error('Enabled API project is outside discovered scopes');
 if(s.config?.name==='storage.googleapis.com')requests.push({apiUrl:'https://storage.googleapis.com/storage/v1/b?project='+project+'&maxResults=1000&projection=noAcl&fields='+encodeURIComponent('items(name,projectNumber,location,storageClass,labels,versioning,lifecycle,softDeletePolicy,retentionPolicy,iamConfiguration(uniformBucketLevelAccess,publicAccessPrevention)),nextPageToken'),quotaProject:project});
