 if(s.config?.name==='firestore.googleapis.com'){
  requests.push({apiUrl:'https://firestore.googleapis.com/v1/projects/'+project+'/databases',quotaProject:project});
  requests.push({apiUrl:'https://firestore.googleapis.com/v1/projects/'+project+'/locations/-/backups',quotaProject:project});
 }
