const c=$('Initialize run').first().json,pages=$input.all().map(i=>i.json);
const expected=$('Prepare additional requests').all().length;
if(pages.some(p=>p.error||p.unreachable?.length)||pages.filter(p=>!p.nextPageToken).length!==expected)throw Error('Additional inventory pagination incomplete');
const requests=[];
for(const page of pages){
 for(const account of page.accounts||[]){
  if(!/^projects\/[^/]+\/serviceAccounts\/[^/]+$/.test(account.name||''))throw Error('Unexpected service account identity');
  requests.push({apiUrl:'https://iam.googleapis.com/v1/'+account.name+'/keys?fields='+encodeURIComponent('keys(name,keyType,keyOrigin,validAfterTime,validBeforeTime,disabled)'),quotaProject:c.identityQuotaProject});
 }
 for(const dataset of page.datasets||[]){
  const ref=dataset.datasetReference||{};
  if(!c.scopes.includes('projects/'+ref.projectId)||!/^[A-Za-z0-9_]+$/.test(ref.datasetId||''))throw Error('Unexpected BigQuery dataset identity');
  // Temporary query-result datasets are execution data, not provisioned infrastructure.
  if(/^_(?:script)?[a-f0-9]{40}$/i.test(ref.datasetId))continue;
  requests.push({apiUrl:'https://bigquery.googleapis.com/bigquery/v2/projects/'+ref.projectId+'/datasets/'+ref.datasetId+'/tables?maxResults=1000',quotaProject:ref.projectId});
 }
 for(const db of page.databases||[]){
  const m=String(db.name||'').match(/^(projects\/[a-z0-9-]+)\/databases\/([A-Za-z0-9()_-]+)$/);
  if(!m||!c.scopes.includes(m[1]))throw Error('Unexpected Firestore database identity');
  for(const suffix of ['/backupSchedules','/collectionGroups/-/indexes','/collectionGroups/-/fields?filter='+encodeURIComponent('indexConfig.usesAncestorConfig=false OR ttlConfig:*')])requests.push({apiUrl:'https://firestore.googleapis.com/v1/'+db.name+suffix,quotaProject:m[1].slice(9)});
 }
}
if(!requests.length)requests.push({apiUrl:'https://cloudasset.googleapis.com/v1/'+c.scopes[0]+'/assets?contentType=RESOURCE&pageSize=1&assetTypes=cloudresourcemanager.googleapis.com%2FProject&fields=readTime',quotaProject:c.billingProject});
if(requests.length>c.maxPages)throw Error('Nested inventory exceeds request limit');
return requests.map(json=>({json}));
